insert  into `cabanggereja`(`idcabang`,`namacabang`,`namacabang_slug`,`alamatlengkap`,`latitude`,`longitude`,`icon`,`deskripsi`,`namagembala`,`notelp`,`jadwalibadah`,`urlfacebook`,`urlinstagram`,`urlyoutube`,`urltwitter`,`urllinkedin`,`gambarsampul`,`statusaktif`) values (4,'GBI El Shaddai Pontianak','cabang-sekadau','Jl. Prof. M.Yamin No.1A, Sungai Bangkong, Kec. Pontianak Kota, Kota Pontianak, Kalimantan Barat 78116','-0.0482368412255885','109.31869089603425',NULL,'<p>GBI El Shaddai Pontianak adalah tempat di mana perjalanan pelayanan El Shaddai dimulai dan terus berkembang sejak tahun 2009.&nbsp;Lokasi&nbsp;ini digembalakan oleh Ps. Yehezkiel Wilan dan Ps. Sandra.<br />\r\nKami juga menyediakan pelayanan anak-anak melalui ESC Kids yang hadir khusus di Ibadah Raya 1, 2, dan 3 &mdash; sehingga seluruh keluarga bisa bertumbuh bersama dalam Tuhan.<br />\r\nKami menantikan kehadiranmu &mdash; mari bertemu dan beribadah bersama!</p>\r\n','Ps. Wilan, M.Th','0855 5000 1187','<p><span style=\"font-size:16px\"><strong>Ibadah Raya 1 Pukul 07.30 - 09.00</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Ibadah Raya 2&nbsp;Pukul 10.30 - 12.00</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Ibadah Raya 3&nbsp;Pukul 16.00 - 17.30</strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong>Ibadah Raya 4&nbsp;Pukul 19.00 - 21.00</strong></span></p>\r\n','','https://www.instagram.com/elshaddai_church?igsh=MTFpODQ2a3B2czFlOA==','https://www.youtube.com/@elshaddaichurchpontianak','','','daniel-tseng-QCjC1KpA4nA-unsplash.jpg','Aktif'),(5,'GBI El Shaddai Serdam','cabang-sanggau','Ruko Dalam Permata Khatulistiwa, Jl. Sui Raya Dalam, Kec. Sungai Raya, Kabupaten Kubu Raya, Kalimantan Barat, 78391','-0.08089807921884773','109.35521990060808',NULL,'','Ps. Johanes Johari. M.Th','0811 5622 238','<p>Ibadah I: Jam 09.00 WIB</p>\r\n','','https://www.instagram.com/esc_serdam?igsh=YXcwNGYycmY1ZDlk','','','','Screenshot_2025-06-06_111910.png','Aktif'),(6,'GBI Mer C Singkawang','cabang-kuburaya','l. Yohana Godang No.65, Kel. Pasiran Kec. Singkawang Barat, Pasiran, Singkawang Barat, Singkawang City, West Kalimantan 79123','0.903759670539345','108.98583412170412',NULL,'','Ps. Askim Astono, SE., MA','-','<p>Ibadah I : Jam 08.00 WIB</p>\r\n','https://www.googleadservices.com/pagead/aclk?sa=L&ai=DChcSEwiGj5fznfGCAxX3qWYCHRX6FDsYABAAGgJzbQ&ase=2&gclid=Cj0KCQiAyKurBhD5ARIsALamXaG88AEztC0-Drfabj6NA9CGkoTbtRCjgykNJc38YrlVnxZcAXL4PScaArbaEALw_wcB&ohost=www.google.com&cid=CAESV-D2vRUWamOPXrauv9DZXq5C','','https://www.youtube.com/channel/UCcZEfg9RmQOvqLgaeqLKX-w','','','bg-cos13.jpg','Aktif'),(7,'GBI Elshaddai Sungai Pinyuh','gbi-elshaddai-sungai-pinyuh','Jalan Jurusan Mempawah Komplek Sutera Indah Residence Sungai Pinyuh','0.280150250892118','109.06763076782228',NULL,'','Pdm.Ferdhinand Purba','','<p>Ibadah : Pukul 10.00 - 12.00 Wib</p>\r\n','','','','','','','Aktif'),(8,'GBI El Shaddai Cabang Siantan','gbi-el-shaddai-cabang-siantan','Jln. Gusti Situt Machmud, Gg. Selat Sumba X, No. 60F, Siantan Tengah, Pontianak Utara','-0.015696286958819135','109.3486511707306',NULL,'','Pdm. Yanto','','','','','','','','','Aktif'),(9,'GBI jemaat gunung Sinai, Siantan ','gbi-jemaat-gunung-sinai,-siantan-','Jalan khatulistiwa gang selat Madura no,37, Siantan Pontianak Utara, Kalimantan barat ','-0.01742899390997374','109.3436622619629',NULL,'','Pdp. Lo Chin Fung Andreas ','','','','','','','','','Aktif'),(10,'GBI CWS','gbi-cws','Jl Kelam Gg. Mandiri','0.08171078773210083','111.57474517822267',NULL,'','Pdt. Diki Raharjo','','','','','','','','','Aktif');

