/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `create_idruangan`() RETURNS varchar(10) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
    DETERMINISTIC
BEGIN
    DECLARE newid  VARCHAR(10);
    DECLARE urutan INT;
